if (JSON.stringify(report.selected_rules) !== JSON.stringify(expected)) { console.error('"'selected_rules mismatch'); process.exit(1); }
const expectedLocations = plan.rules.flatMap(rule => rule.files.flatMap(file => file.locations.map(location => "'`${rule.rule}|${file.relative_path}|${location.line}:${location.column}`)));
const actualLocations = report.entity_repairs.flatMap(entry => entry.locations.map(location => `${entry.rule}|${entry.relative_path}|${location.line}:${location.column}`));
