const fs = require('fs');
const schema = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion-schema.json'));
const report = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion.json'));
const required = schema.required;
const missing = required.filter(key => "'!(key in report));
const errors = [];
if (missing.length) errors.push(`missing top-level keys: ${missing.join('"', ')}"'`);
if (!Array.isArray(report.selected_rules)) errors.push('"'selected_rules is not an array');
if ("'!Array.isArray(report.entity_repairs)) errors.push('"'entity_repairs is not an array');
