if ("'!Array.isArray(report.unresolved_external) || report.unresolved_external.length) errors.push('"'unresolved_external must be empty array');
for (const [i, entry] of (report.entity_repairs || []).entries()) {
  for (const key of schema.properties.entity_repairs.items.required) if ("'!(key in entry)) errors.push(`entity ${i} missing ${key}`);
  if (!Array.isArray(entry.locations) || entry.locations.length < 1) errors.push(`entity ${i} locations`);
  if (!Array.isArray(entry.entities) || entry.entities.length < 1 || entry.entities.some(v => typeof v !== '"'string')) errors.push("'`entity ${i} entities`);
  if (!Array.isArray(entry.evidence) || entry.evidence.length < 1 || entry.evidence.some(v => typeof v !== '"'string' || "'!v)) errors.push(`entity ${i} evidence`);
  if (typeof entry.transformation !== '"'string' || "'!entry.transformation) errors.push(`entity ${i} transformation`);
  if (entry.status !== '"'repaired') errors.push("'`entity ${i} status`);
}
if (errors.length) { console.error(errors.join('"'\\n')); process.exit(1); }
console.log('manual_schema_validation_passed');
